# Multi-query search fused with Reciprocal Rank Fusion (RRF)
# score(doc) = sum over lists of 1 / (60 + rank)
rankings = {
    "refund policy":        ["d3", "d1", "d7"],
    "how to get money back": ["d5", "d3", "d2"],
    "return an order":      ["d3", "d5", "d9"],
}
K = 60
scores = {}
for query, ranked in rankings.items():
    print(query, "->", ranked)
    for rank, doc in enumerate(ranked, start=1):
        scores[doc] = scores.get(doc, 0.0) + 1.0 / (K + rank)
fused = sorted(scores.items(), key=lambda kv: -kv[1])
print("fused:")
for doc, s in fused[:4]:
    print(" ", doc, round(s, 4))
# d3 appears in all three lists, so it wins even though it was not first everywhere

# Parent-child chunking: match small children, return deduped parents
parents = {
    "p1": "Returns: items can be returned within 30 days. Refunds go to the original card.",
    "p2": "Shipping: orders ship in 2 days. Express costs extra.",
}
# Children are single sentences that remember their parent id
children = []
for pid, text in parents.items():
    for s in text.split(". "):
        children.append((pid, s.strip(".")))

query = set("refunds original card".split())
def score(child):
    return len(query & set(child[1].lower().replace(":", "").split()))

ranked = [c for c in sorted(children, key=lambda c: -score(c))[:3] if score(c) > 0]
print("top children:", [(c[0], score(c)) for c in ranked])
seen, result = set(), []
for pid, _ in ranked:               # dedupe: each parent returned once
    if pid not in seen:
        seen.add(pid)
        result.append(pid)
print("parents sent to prompt:", result)
print(parents[result[0]])
